const headerSecret = ($json.headers?.['x-n8n-payment-secret'] || $json.headers?.['X-N8N-Payment-Secret'] || '').trim();
const expectedSecret = ($env.N8N_PAYMENT_WEBHOOK_SECRET || '').trim();
if (!expectedSecret || headerSecret !== expectedSecret) {
  return [{ json: { ok: false, stop: true, httpStatus: 401, message: 'secret ไม่ถูกต้อง' } }];
}
const body = $json.body || $json;
if (!body.payment?.id || !body.payment?.amount || !body.slip?.base64 || !body.callback?.url || !body.callback?.secret) {
  return [{ json: { ok: false, stop: true, httpStatus: 422, message: 'ข้อมูลสลิปไม่ครบ' } }];
}
return [{ json: { ok: true, stop: false, payment: body.payment, slip: body.slip, callback: body.callback, customer: body.customer, lawyer: body.lawyer } }];

// จุดนี้สามารถต่อ OCR/AI Vision เพิ่มได้
// ให้ใส่ผล OCR เป็นตัวแปร slipText แล้วเปรียบเทียบยอดกับ payment.amount
const payment = $json.payment;
const hasSlip = Boolean($json.slip?.base64);
let decision = 'manual_review';
let confidence = 0.65;
let note = 'n8n รับสลิปแล้ว แต่ยังไม่ได้ต่อ OCR/AI จึงส่งให้แอดมินตรวจต่อ';

// ตัวอย่าง logic หลังต่อ OCR แล้ว:
// if (amountFromSlip === payment.amount && confidenceFromOcr >= 0.9) decision = 'approved';
// if (amountFromSlip !== payment.amount && confidenceFromOcr >= 0.85) decision = 'rejected';

if (!hasSlip) {
  decision = 'rejected';
  confidence = 0.9;
  note = 'ไม่พบไฟล์สลิปใน payload';
}

return [{ json: { payment_id: payment.id, decision, confidence, note, callback: $json.callback } }];
